-- Static data of the info and help windows for the Unity client (O433 phase 5, track Q), written from the main client's generated data files:
--   Resources/Codex.json        client/overlay/modules/game_codex/codex_data.lua            (itself generated by server/tools/gen_codex_data.lua)
--   Resources/HowItWorks.json   client/overlay/modules/game_howitworks/howitworks_data.lua  (gen_howitworks_data.lua)
--   Resources/HelpSearch.json   client/overlay/modules/game_helpsearch/helpsearch_data.lua  (gen_guide_data.lua)
--   Core/InfoLiftData.cs        client/overlay/modules/client_chaos_infolift/info_lifts.lua (gen_info_lift.py on the pair)
-- Run from the repository root: luajit unity/tools/gen_info_data.lua [--check]   (also lua5.3). --check exits 1 when a committed file is stale.
-- Format of the JSON files: sorted-key compact JSON of the same tables the Lua files hold (CodexData, HowData, HelpSearchData); a list is an array,
-- a table with names is an object (an empty table is an empty array). Read by Core/Codex.cs, Core/HowItWorks.cs and Core/HelpSearch.cs.
local root = arg and arg[0] and arg[0]:match("^(.*)/unity/tools/") or "."
local mods = root .. "/client/overlay/modules/"
local resources = root .. "/unity/Client/Assets/Chaos/Resources/"
local core = root .. "/unity/Client/Assets/Chaos/Core/"

-- sorted-key JSON, no spaces
local function esc(s)
  return '"' .. s:gsub('[%c"\\]', function(c)
    local map = {['"'] = '\\"', ['\\'] = '\\\\', ['\n'] = '\\n', ['\t'] = '\\t', ['\r'] = '\\r'}
    return map[c] or string.format("\\u%04x", c:byte())
  end) .. '"'
end

local function enc(v)
  local tv = type(v)
  if tv == "string" then return esc(v) end
  if tv == "number" then
    if v == math.floor(v) then return string.format("%d", v) end
    return string.format("%.4g", v)
  end
  if tv == "boolean" then return tostring(v) end
  if tv == "table" then
    if #v > 0 or next(v) == nil then
      local parts = {}
      for i = 1, #v do parts[i] = enc(v[i]) end
      return "[" .. table.concat(parts, ",") .. "]"
    end
    local ks = {}
    for k in pairs(v) do
      if type(k) == "string" and k:sub(1, 1) ~= "_" then ks[#ks + 1] = k end
    end
    table.sort(ks)
    local parts = {}
    for _, k in ipairs(ks) do parts[#parts + 1] = esc(k) .. ":" .. enc(v[k]) end
    return "{" .. table.concat(parts, ",") .. "}"
  end
  error("cannot encode " .. tv)
end

local outputs = {}

local function json(file, dataFile, global)
  dofile(mods .. dataFile)
  outputs[#outputs + 1] = {path = resources .. file, text = enc(_G[global]) .. "\n"}
end

json("Codex.json", "game_codex/codex_data.lua", "CodexData")
json("HowItWorks.json", "game_howitworks/howitworks_data.lua", "HowData")
json("HelpSearch.json", "game_helpsearch/helpsearch_data.lua", "HelpSearchData")

-- the info lifts: look type -> sprite pixels the name and bars of a player or an NPC go up
dofile(mods .. "client_chaos_infolift/info_lifts.lua")
do
  local looks = {}
  for look, lift in pairs(ChaosInfoLifts) do
    if type(look) == "number" and type(lift) == "number" and lift > 0 then looks[#looks + 1] = look end
  end
  table.sort(looks)
  local buf = {}
  buf[#buf + 1] = "// GENERATED by unity/tools/gen_info_data.lua from client/overlay/modules/client_chaos_infolift/info_lifts.lua. Do not edit."
  buf[#buf + 1] = "// Names over tall looks: per look type how many sprite pixels (1x) the name and bars of a player or an NPC wearing it go up (see InfoLift.cs)."
  buf[#buf + 1] = "namespace Chaos.Core"
  buf[#buf + 1] = "{"
  buf[#buf + 1] = "    public static partial class InfoLiftData"
  buf[#buf + 1] = "    {"
  buf[#buf + 1] = string.format("        public const string Dat = %q;", ChaosInfoLifts.dat or "")
  buf[#buf + 1] = "        public static readonly int[] Table ="
  buf[#buf + 1] = "        {"
  local line = {}
  for i, look in ipairs(looks) do
    line[#line + 1] = string.format("%d, %d", look, ChaosInfoLifts[look])
    if #line == 8 or i == #looks then
      buf[#buf + 1] = "            " .. table.concat(line, ", ") .. ","
      line = {}
    end
  end
  buf[#buf + 1] = "        };"
  buf[#buf + 1] = "    }"
  buf[#buf + 1] = "}"
  outputs[#outputs + 1] = {path = core .. "InfoLiftData.cs", text = table.concat(buf, "\n") .. "\n"}
end

local check = arg and arg[1] == "--check"
local stale = false
for _, o in ipairs(outputs) do
  if check then
    local f = io.open(o.path, "rb")
    local have = f and f:read("*a") or nil
    if f then f:close() end
    if have ~= o.text then
      io.stderr:write(o.path .. " is stale: run luajit unity/tools/gen_info_data.lua\n")
      stale = true
    end
  else
    local f = assert(io.open(o.path, "wb"))
    f:write(o.text)
    f:close()
    print("wrote " .. o.path .. " (" .. #o.text .. " bytes)")
  end
end
if check then
  if stale then os.exit(1) end
  print("info data: ok (" .. #outputs .. " files)")
end
